   const metrics=entry.analysis.localInventory?.pageMetrics||[];if(metrics.length){const list=document.createElement('ul');list.className='learning-page-metrics';for(const metric of metrics){const label=`${learningT('Seite')} ${metric.number} · ${metric.width} × ${metric.height} pt${metric.scanLike?` · ${metric.ocrPerformed?`${learningT('lokale OCR')}${metric.ocrConfidence!==null?` ${metric.ocrConfidence}%`:''}`:learningT('Scan, visuell analysiert; lokale OCR nicht verfügbar')}`:''}`;list.append(safeNode('li',label));}card.append(list);}
