   if((entry.rules||[]).length){details.append(safeNode('h4',learningT('Stilregeln')));for(const rule of entry.rules){const row=document.createElement('div');row.className='learning-edit-row';const pick=checkboxRow('',true);const edit=textEditor(rule);pick.wrap.querySelector('span').remove();pick.input.setAttribute('aria-label',`${learningT('Regel auswählen')}: ${rule}`);edit.setAttribute('aria-label',learningT('Regel bearbeiten'));row.append(pick.wrap,edit);pick.input.dataset.ruleSource=rule;row.dataset.noTranslate='';details.append(row);}}
