   if(entry.analysis.observations?.length){details.append(safeNode('h4',learningT('Beobachtungen mit Belegseiten')));for(const observation of entry.analysis.observations){const row=document.createElement('div');row.className='learning-edit-row';const pick=checkboxRow(`${observation.category} · ${observation.certainty} · ${learningT('Seiten')} ${(observation.pages||[]).join(', ')||'—'}`,true);const edit=textEditor(observation.text);edit.setAttribute('aria-label',learningT('Beobachtung bearbeiten'));pick.input.setAttribute('aria-label',`${learningT('Beobachtung auswählen')}: ${observation.text}`);pick.input.value=observation.id;row.append(pick.wrap,edit);row.dataset.noTranslate='';details.append(row);}}
