  if(entry.status==='pending_review'&&entry.analysis?.complete){const approve=document.createElement('button');approve.className='primary';approve.textContent=learningT('Auswahl übernehmen');approve.onclick=()=>void workspaceTask(async()=>{const rules=[],ruleEdits=[],fieldLabels=[...card.querySelectorAll('.learning-field-selection:checked')].map(input=>input.value),observationIds=[],observationEdits=[],terminologyIds=[],terminologyEdits=[];for(const row of card.querySelectorAll('.learning-edit-row')){const checkbox=row.querySelector('input[type=checkbox]'),editor=row.querySelector('textarea');if(!checkbox?.checked)continue;if(checkbox.dataset.ruleSource!==undefined){rules.push(checkbox.dataset.ruleSource);if(editor.value!==checkbox.dataset.ruleSource)ruleEdits.push({source:checkbox.dataset.ruleSource,text:editor.value});}else{observationIds.push(checkbox.value);if(editor.value!==entry.analysis.observations.find(item=>item.id===checkbox.value)?.text)observationEdits.push({id:checkbox.value,text:editor.value});}}for(const row of card.querySelectorAll('.learning-term-row')){const checkbox=row.querySelector('input[type=checkbox]');if(!checkbox.checked)continue;terminologyIds.push(checkbox.value);const original=entry.analysis.terminology.find(item=>item.id===checkbox.value);const fields=row.querySelectorAll('textarea');if(fields[0].value!==original.source||fields[1].value!==original.target)terminologyEdits.push({id:checkbox.value,source:fields[0].value,target:fields[1].value});}learningEntries=(await localRequest('/api/learning/update',{id:entry.id,approve:true,rules,ruleEdits,fieldLabels,observationIds,observationEdits,terminologyIds,terminologyEdits,applyLayout:card.querySelector('.learning-layout-approved')?.checked===true}).then(r=>r.json())).entries;renderLearning();});actions.append(approve);}
